provenance.sourcePrompt:
Biographics elegant PiP card — Sherlock Holmes. 6 seconds, 1920x1080, SILENT.

Design language: asymmetric, editorial, film-grade. NOT a box with a label bar. The video window floats on a deep maroon field with generous breathing room. Text is typographically separated — role name sits away from the window, connected only by a thin diagonal accent line. Inspired by premium documentary title cards and editorial magazine spreads.

```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;1,400;1,700&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;}
body,#scene{
  width:1920px;height:1080px;overflow:hidden;
  background:#3d0a0a;
}
#scene{position:relative;}

/* ── subtle radial vignette on bg ── */
#bg-vignette{
  position:absolute;top:0;left:0;width:100%;height:100%;
  background:radial-gradient(ellipse at 65% 50%, #5a1212 0%, #2a0606 55%, #1a0404 100%);
  z-index:0;
}

/* ── video window — offset right-of-center ── */
#win-wrap{
  position:absolute;
  top:50%; left:55%;
  transform:translate(-50%,-50%);
  z-index:10;
  opacity:0;
}
/* thin top accent line above window */
#win-top-line{
  width:0;height:1px;
  background:rgba(240,236,228,0.35);
  margin-bottom:0;
}
#win{
  width:580px;height:326px;
  overflow:hidden;
  position:relative;
}
#win video{width:100%;height:100%;object-fit:cover;display:block;}
/* inner shadow on video */
#win::after{
  content:'';position:absolute;top:0;left:0;width:100%;height:100%;
  box-shadow:inset 0 0 40px rgba(30,4,4,0.55);
  pointer-events:none;
}
/* thin bottom line below window */
#win-bot-line{
  width:0;height:1px;
  background:rgba(240,236,228,0.35);
  margin-top:0;
}

/* ── left text block — separated, floats left ── */
#text-block{
  position:absolute;
  top:50%;left:96px;
  transform:translateY(-50%);
  z-index:10;
  opacity:0;
  width:360px;
}
#text-chapter{
  font-family:'Playfair Display',Georgia,serif;
  font-size:11px;font-style:italic;
  color:rgba(220,190,165,0.65);
  letter-spacing:0.45em;text-transform:uppercase;
  margin-bottom:20px;
}
#text-rule{
  width:0;height:1px;
  background:linear-gradient(to right,rgba(220,190,165,0.55),transparent);
  margin-bottom:20px;
}
#text-role{
  font-family:'Playfair Display',Georgia,serif;
  font-size:56px;font-weight:700;font-style:italic;
  color:#f0ece4;
  line-height:1.05;
  letter-spacing:0.01em;
}
#text-source{
  font-family:'Playfair Display',Georgia,serif;
  font-size:13px;font-weight:400;
  color:rgba(220,190,165,0.65);
  letter-spacing:0.22em;text-transform:uppercase;
  margin-top:16px;
}
/* small maroon dot separator */
#text-dot{
  display:inline-block;
  width:5px;height:5px;
  background:#8b2e2e;
  border-radius:50%;
  margin:14px 0 0 2px;
  vertical-align:middle;
  opacity:0;
}

/* ── diagonal connector line from text to window ── */
#connector{
  position:absolute;
  top:50%;left:456px; /* between text block right edge and window left */
  width:0;height:1px;
  background:linear-gradient(to right,rgba(139,46,46,0.5),transparent);
  transform:translateY(-50%);
  z-index:5;
}
</style>
</head>
<body>
<div id="scene">
  <div id="bg-vignette"></div>
  <div id="connector"></div>

  <!-- Left text block -->
  <div id="text-block">
    <div id="text-chapter">The Breakout · 2010</div>
    <div id="text-rule"></div>
    <div id="text-role">Sherlock<br>Holmes</div>
    <div id="text-dot"></div>
    <div id="text-source">BBC One &nbsp;·&nbsp; 2010 – 2017</div>
  </div>

  <!-- Right video window -->
  <div id="win-wrap">
    <div id="win-top-line"></div>
    <div id="win">
      <video autoplay muted loop playsinline>
        <source src="{{roleVid}}" type="video/mp4">
      </video>
    </div>
    <div id="win-bot-line"></div>
  </div>
</div>

<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded', function(){
  var tl = gsap.timeline();

  // text block slides in from left
  tl.to('#text-block', {opacity:1, x:0, duration:0.7, ease:'power3.out',
    startAt:{opacity:0, x:-24}}, 0.3)
  // chapter label
    .to('#text-rule',   {width:120, duration:0.4, ease:'power2.out'}, 0.55)
  // text dot appears
    .to('#text-dot',    {opacity:1, duration:0.3, ease:'power2.out'}, 0.9)
  // connector line draws right
    .to('#connector',   {width:130, duration:0.5, ease:'power2.out'}, 0.7)
  // video window fades + slides in from right
    .to('#win-wrap',    {opacity:1, x:0, duration:0.7, ease:'power3.out',
      startAt:{opacity:0, x:20}}, 0.55)
  // top + bottom lines expand
    .to('#win-top-line',{width:580, duration:0.4, ease:'power2.out'}, 0.65)
    .to('#win-bot-line',{width:580, duration:0.4, ease:'power2.out'}, 0.75)

  // hold until exit
    .to('#text-block',  {opacity:0, x:-18, duration:0.5, ease:'power2.in'}, 5.2)
    .to('#connector',   {width:0,   duration:0.3, ease:'power2.in'}, 5.2)
    .to(['#win-top-line','#win-bot-line'], {width:0, duration:0.3, ease:'power2.in'}, 5.3)
    .to('#win-wrap',    {opacity:0, x:16,  duration:0.5, ease:'power2.in'}, 5.3);
});
</script>
</body>
</html>
```
